from pathlib import Path
p=Path(__file__).resolve().parents[1]/'src/studio.mjs'
s=p.read_text(encoding='utf-8').replace("let body=await r.text();if(route==='/'){", "let body=await r.text();if(route==='/'&&r.status>=400)return {status:r.status,type:'text/html',body:failurePreview(r.status)};if(route==='/'){")
s+='''\nfunction failurePreview(status){return `<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Sample outage detected</title><style>body{margin:0;background:#11141b;color:#f3f4f7;font:14px system-ui,sans-serif;display:grid;place-items:center;min-height:300px}main{max-width:520px;padding:32px;text-align:center}strong{color:#ec3445;font-size:12px;letter-spacing:1px}h1{font-size:24px}p{color:#9ca4b5;line-height:1.7}code{background:#20232e;padding:7px 12px;border-radius:7px}</style><main><strong>LOCAL SAMPLE · HTTP ${status}</strong><h1>Sample outage detected</h1><p>This is the disposable sample, not your published website. Its real HTTP response is failing.</p><p>Choose <b>Analyze with AI</b> in the workspace, then review and approve the registered repair. Independent checks must pass before recovery is confirmed.</p><code>HTTP ${status} · recovery not yet verified</code></main></html>`;}\n'''
p.write_text(s,encoding='utf-8')
